import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import Teachernav from "./teachernav";
import Style1 from "./teacher.module.css";
import toast from "react-hot-toast";

function UpdateStudent() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [user, setUser] = useState({
    name: "",
    roll: "",
    class: "",
  });

  // Fetch student details by ID
  useEffect(() => {
    const fetchUser = async () => {
      try {
        const res = await axios.get(`http://localhost:8009/api/user/${id}`);
        // Ensure class1 is string (for matching select option)
        const fetchedUser = res.data;
        setUser({
          ...fetchedUser,
          class: String(fetchedUser.class || ""), // convert to string
        });
      } catch (err) {
        toast.error("Failed to fetch student details");
      }
    };
    fetchUser();
  }, [id]);

  // Handle input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setUser({ ...user, [name]: value });
  };

  // Handle update submit
  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      await axios.put(`http://localhost:8009/api/update/user/${id}`, user);
      toast.success("Student details updated successfully!");
      navigate("/viewstudent");
    } catch (err) {
      toast.error("Error updating student");
    }
  };

  return (
    <>
      <Teachernav />
      <div className={Style1.main1}>
        <h2 className={Style1.view_heading}>Update Student Details</h2>

        <form className={Style1.form} onSubmit={handleUpdate}>
          <div className={Style1.arrange}>
            <label className={Style1.label}>Name:</label>
            <input
              className={Style1.input1}
              type="text"
              name="name"
              value={user.name}
              onChange={handleChange}
              placeholder="Enter name"
            />
          </div>

          <div className={Style1.arrange}>
            <label className={Style1.label}>Roll:</label>
            <input
              className={Style1.input1}
              type="text"
              name="roll"
              value={user.roll}
              onChange={handleChange}
              placeholder="Enter roll number"
            />
          </div>

          <div className={Style1.arrange}>
            <label className={Style1.label}>Class:</label>
            <select
              className={Style1.input1}
              name="class1"
              value={user.class1}
              onChange={handleChange}
            >
              <option value="">Select Class</option>
              <option value="10">10</option>
              <option value="9">9</option>
              <option value="8">8</option>
              <option value="7">7</option>
              <option value="6">6</option>
              <option value="5">5</option>
              <option value="4">4</option>
              <option value="3">3</option>
              <option value="2">2</option>
              <option value="1">1</option>
            </select>
          </div>

          <button type="submit" className={Style1.submit}>
            Update
          </button>
        </form>
      </div>
    </>
  );
}

export default UpdateStudent;
